        if run_at is None:
            run_at = now + timedelta(seconds=delay or 0.0)
        seq = next(self._seq)
        job = Job(
            id=f"job-{seq:06d}",
            job_type=job_type,
            run_at=run_at,
            created_at=now,
            payload=dict(payload or {}),
            seq=seq,
        )
